        `;
        return rowToInstallation(rows[0]);
      }

      // Activating: do the reject/transfer atomically. A transaction-scoped
      // advisory lock keyed on the tenant tuple serializes ALL concurrent
      // activations for that tuple (across replicas — the lock lives in
      // Postgres, not memory), so the demote+activate is a single ordered step
      // and the partial unique index `app_installations_active_tenant` is never
      // contended. This is the convergence guarantee under N replicas, mirroring
      // the repo's pg_advisory_xact_lock pattern (auth/credentials.ts).
      return sql.begin(async (tx) => {
        await tx.unsafe("SELECT pg_advisory_xact_lock(hashtext($1))", [
          activeTenantLockTag(install),
        ]);

        // Cross-org fence (atomic, under the lock): when the caller forbids a
        // silent transfer, refuse to demote a DIFFERENT-org active owner. Checked
        // here — not before the lock — so a concurrent activation on another pod
        // cannot slip a foreign owner in between the check and the demote.
        if (install.blockCrossOrgTransfer) {
          const fenceMatch = install.crossOrgFenceMetadataMatch;
          // A cross-key claim (e.g. Grid org-wide vs per-workspace) touches a
          // DIFFERENT tenant tuple, so the tuple lock above does NOT serialize it.
          // Take a second lock on the shared metadata grouping key so the two
          // racers order deterministically before either reads the fence.
          if (fenceMatch) {
            await tx.unsafe("SELECT pg_advisory_xact_lock(hashtext($1))", [
              fenceGroupLockTag(
                install.provider,
                install.providerAppId,
                fenceMatch.key,
                fenceMatch.value
              ),
            ]);
          }
          // The grouping arm matches a foreign row sharing the value ONLY when a
          // scope-spanning install is involved: either WE span the group
          // (`claimIsScopeWide` → any foreign sibling overlaps) or the FOREIGN row
          // itself spans it (its `scopeFlagKey` is true). Two independent
          // per-workspace siblings (neither scope-wide) never match, so a genuine
          // second-workspace claim of the same Grid into another org is allowed.
          const claimScopeWide = fenceMatch?.claimIsScopeWide === true;
          const foreign = await tx`
            SELECT organization_id FROM app_installations
            WHERE provider = ${install.provider}
              AND provider_app_id = ${install.providerAppId}
              AND status = 'active'
              AND organization_id <> ${install.organizationId}
              AND (
                (
                  provider_instance = ${install.providerInstance}
                  AND external_tenant_id = ${install.externalTenantId}
                )
                OR (
                  ${fenceMatch ? fenceMatch.value : null}::text IS NOT NULL
                  AND metadata ->> ${fenceMatch ? fenceMatch.key : ""} = ${
                    fenceMatch ? fenceMatch.value : null
                  }
                  AND (
                    ${claimScopeWide}
                    OR (metadata -> ${
                      fenceMatch ? fenceMatch.scopeFlagKey : ""
                    }) = 'true'::jsonb
                  )
                )
              )
            LIMIT 1
          `;
          if (foreign.length > 0) {
            throw new CrossOrgTransferBlockedError(
              foreign[0].organization_id as string
            );
          }
        }

        // Demote any active row for this tuple owned by a DIFFERENT org — a
        // transfer takes the single active slot from the prior owner. (A same-org
        // active row is left as-is; it becomes the row we refresh below.) This is
        // a no-op when no different-org active row exists.
        await tx`
          UPDATE app_installations
          SET status = 'suspended', updated_at = now()
          WHERE provider = ${install.provider}
            AND provider_instance = ${install.providerInstance}
            AND provider_app_id = ${install.providerAppId}
            AND external_tenant_id = ${install.externalTenantId}
            AND status = 'active'
            AND organization_id <> ${install.organizationId}
        `;

        // Find an EXISTING row for the TARGET (org, tuple) — active or demoted —
        // so an install/reinstall/return-transfer REACTIVATES that single row in
        // place instead of inserting a duplicate. This is the invariant: at most
        // ONE row per (provider, tuple, org). Without it, an A->B->A transfer
        // would leave org A with two rows (the original demoted one + a fresh
        // active one), and listByOrg/list would return duplicate ids.
        const existingRows = await tx`
          SELECT * FROM app_installations
          WHERE provider = ${install.provider}
            AND provider_instance = ${install.providerInstance}
            AND provider_app_id = ${install.providerAppId}
            AND external_tenant_id = ${install.externalTenantId}
            AND organization_id = ${install.organizationId}
          ORDER BY (status = 'active') DESC, updated_at DESC, id DESC
          LIMIT 1
        `;
        const existing = existingRows[0];

        if (existing) {
          // Reactivate-and-refresh the target org's existing row in place (covers
          // same-org reinstall AND a return transfer A->B->A: org A's demoted row
          // is reused, not duplicated). Merge any preserve-requested metadata keys
          // from the existing row (their value wins over the incoming one) — the
          // race-safe durable-id claim: a caller that minted its own id but lost
          // the insert race reads back the winner's id instead of clobbering it.
          const mergedMetadata = { ...metadata };
          const existingMetadata =
            (existing.metadata as Record<string, any> | null) ?? {};
          for (const key of install.preserveMetadataKeysOnUpdate ?? []) {
            if (existingMetadata[key] !== undefined) {
              mergedMetadata[key] = existingMetadata[key];
            }
          }
          const rows = await tx`
            UPDATE app_installations
            SET status = 'active',
  }>;
  const row = rows[0];
  if (!row) return null;
  const enc = row.metadata.bot_token_enc;
  if (typeof enc !== "string" || !enc) return null;
  return {
    id: String(row.id),
    teamId: row.external_tenant_id,
    teamName:
      typeof row.metadata.team_name === "string"
        ? row.metadata.team_name
        : null,
    botUserId:
      typeof row.metadata.bot_user_id === "string"
        ? row.metadata.bot_user_id
        : null,
    installerUserId:
      typeof row.metadata.installer_user_id === "string"
        ? row.metadata.installer_user_id
        : null,
    botToken: decrypt(enc),
    isEnterpriseInstall: row.metadata.is_enterprise_install === true,
    enterpriseId:
      typeof row.metadata.enterprise_id === "string"
        ? row.metadata.enterprise_id
        : null,
  };
}

/**
 * Claim a pending (unclaimed) Slack workspace into an org. The first UPDATE is
 * the authoritative, durable claim: it atomically assigns the pending row to
 * one org before any secret-store or activation work begins. A racing org's
 * compare-and-set returns no row, so generic active-install transfer semantics
 * can never turn a second pending claim into an ownership steal.
 *
 * The claimed row deliberately stays `pending` until
 * {@link upsertSlackInstallByTeam} has persisted the bot token. That function
 * finds this org-owned row and flips it active in place. If token persistence or
 * activation fails, the encrypted token remains on the durable pending row and
 * the SAME org can retry; a different org still cannot claim it.
 *
 * Caller is responsible for authorizing the claim (workspace-admin check)
 * BEFORE invoking this. Returns the stable `slackinst-<uuid>` install id.
 *
 * When `confirmMove` is false and the workspace is already ACTIVE in another
 * org, activation throws {@link CrossOrgTransferBlockedError} — the atomic fence
 * against a silent second-org claim stealing the active slot. The durable
 * pending-row claim is rolled back to org-less so a genuine first claim can
 * still succeed once the user confirms the move (or claims elsewhere).
 */
export async function claimSlackPendingInstall(
  store: AppInstallationStore,
  secretStore: WritableSecretStore,
  pending: SlackPendingInstall,
  organizationId: string,
  confirmMove = false
): Promise<{ installationId: string }> {
  const sql = getDb();
  const claimed = await sql`
    UPDATE app_installations
    SET organization_id = ${organizationId}, updated_at = now()
    WHERE id = ${pending.id}::bigint
      AND provider = ${SLACK_PROVIDER}
      AND provider_instance = ${SLACK_PROVIDER_INSTANCE}
      AND provider_app_id = ${SLACK_PROVIDER_APP_ID}
      AND external_tenant_id = ${pending.teamId}
      AND status = 'pending'
      AND (organization_id IS NULL OR organization_id = ${organizationId})
    RETURNING id
  `;
  if (claimed.length === 0) {
    throw new Error("Slack workspace pending install was already claimed");
  }

  let row: SlackInstallationRow;
  try {
    row = await upsertSlackInstallByTeam(
      store,
      secretStore,
      organizationId,
      pending.teamId,
      {
        teamName: pending.teamName ?? undefined,
        botUserId: pending.botUserId ?? undefined,
        botToken: pending.botToken,
        installerUserId: pending.installerUserId ?? undefined,
        enterpriseId: pending.enterpriseId,
        isEnterpriseInstall: pending.isEnterpriseInstall,
        blockCrossOrgTransfer: !confirmMove,
      }
    );
  } catch (err) {
    if (err instanceof CrossOrgTransferBlockedError) {
      // The fence tripped: this workspace is already active in another org and
      // the move was not confirmed. Release the durable pending-row claim (back
      // to org-less, still pending) so a genuine first claim from the rightful
      // org — or a later confirmed move — can still proceed. Never leave the row
      // stranded under an org that failed to activate.
      await sql`
        UPDATE app_installations
        SET organization_id = NULL, updated_at = now()
        WHERE id = ${pending.id}::bigint
          AND provider = ${SLACK_PROVIDER}
          AND provider_app_id = ${SLACK_PROVIDER_APP_ID}
          AND external_tenant_id = ${pending.teamId}
          AND organization_id = ${organizationId}
          AND status = 'pending'
      `;
    }
    throw err;
  }
  // Usually the reserved row was activated in place. If a same-org active row
  // already existed, the generic upsert refreshed that row instead; retire only
  // THIS successfully consumed pending row, never a newer reinstall.
  await sql`
    DELETE FROM app_installations
    WHERE id = ${pending.id}::bigint
      AND provider = ${SLACK_PROVIDER}
      AND provider_app_id = ${SLACK_PROVIDER_APP_ID}
      AND external_tenant_id = ${pending.teamId}
      AND organization_id = ${organizationId}
      AND status = 'pending'
  `;
  return { installationId: row.id };
}
/**
 * GitHub App install callback (app-installation design §4.4, PR5).
 *
 * `linkGithubAppInstallation` is the callback's pure core: given an org + a
 * GitHub `installation_id`, it must
 *   1. upsert an active `app_installations` row for the tenant tuple, and
 *   2. create (or relink) the org's `github` connector connection with
 *      `config.installation_ref` = the install id — the shape
 *      resolveExecutionAuth reads to mint a tenant-scoped token.
 *
 * It must be idempotent: a re-install / callback retry reuses the existing
 * install + connection instead of duplicating either.
 */

