import { createLogger } from "@lobu/core";
import type { Context } from "hono";
import { getDb } from "../../../db/client.js";
import {
  getCachedMembershipRole,
  getCachedOrgBySlug,
} from "../../../workspace/multi-tenant.js";

const logger = createLogger("install-org");

/** The authenticated user id stamped onto the request by `createLobuAuthBridge`. */
function readUserId(c: Context): string | null {
  const user = c.get("user" as never) as { id?: string } | null | undefined;
  return typeof user?.id === "string" && user.id.length > 0 ? user.id : null;
}

/**
 * Resolve the active organization id for the current request.
 *
 * Priority:
 *  1. `c.get('organizationId')` — set by the lobuApp wrapper after
 *     `resolveDefaultOrgId(user.id)` (see `lobu/gateway.ts`). This is the
 *     value Postgres-backed stores read via AsyncLocalStorage, so binding
 *     install state to it keeps the OAuth flow aligned with where the
 *     resulting connection row will be written.
 *  2. `c.get('session')?.activeOrganizationId` — better-auth's stamped
 *     active org, used when the wrapper hasn't run (rare; defensive).
 *
 * Returns `null` if neither is present — caller must reject the request
 * (after consulting {@link resolveSingleTenantOrgId} for the self-host
 * fallback).
 */
function readSessionOrgId(c: Context): string | null {
  const fromContext = c.get("organizationId" as never) as
    | string
    | null
    | undefined;
  if (typeof fromContext === "string" && fromContext.length > 0) {
    return fromContext;
  }
  const session = c.get("session" as never) as
    | { activeOrganizationId?: string | null }
    | null
    | undefined;
  const fromSession = session?.activeOrganizationId;
  if (typeof fromSession === "string" && fromSession.length > 0) {
    return fromSession;
  }
  return null;
}

/**
 * Self-host fallback: when there's exactly one organization row in the
 * database, return its id. This keeps install routes usable on
 * single-tenant deployments where the route is mounted without the
 * lobuApp session middleware that populates `c.get('organizationId')`.
 *
 * Returns `null` when zero or more than one org rows exist — in those
 * cases the caller must reject; we won't silently pick a tenant.
 */
async function resolveSingleTenantOrgId(): Promise<string | null> {
  try {
    const sql = getDb();
    const rows = (await sql`
      SELECT id FROM organization LIMIT 2
    `) as Array<{ id: string }>;
    if (rows.length === 1) return rows[0]!.id;
    return null;
  } catch (err) {
    logger.warn(
      { err: String(err) },
      "Single-tenant org lookup failed — treating as ambiguous"
    );
    return null;
  }
}

/**
 * Resolve an EXPLICIT install target org supplied by the UI (`?org=<slug|id>`),
 * authorized by membership. This is the org the user was actually viewing when
 * they clicked "Install" — the single source of truth for where the connection
 * is created. It intentionally does NOT fall back to the ambient "active org":
 * that silently drifts from the UI selection (the connectors page can show org A
 * while the session's active org is B), which lands installs in the wrong tenant.
 *
 * Returns the resolved org id only when the request's user is a member of it.
 * On self-host (no authenticated user) the requested org is honored only when it
 * is the sole tenant. Returns `null` otherwise — the caller MUST reject rather
 * than silently retarget.
 */
async function resolveRequestedOrgId(
  c: Context,
  requested: string
): Promise<string | null> {
  // The UI passes the org slug from its route; fall back to treating the value
  // as a raw org id when it doesn't resolve as a slug. Membership gates both.
  let orgId: string | null = null;
  try {
    const bySlug = await getCachedOrgBySlug(requested);
    orgId = bySlug?.id ?? null;
  } catch (err) {
    logger.warn(
      { err: String(err), requested },
      "Requested-org slug lookup failed"
    );
  }
  if (!orgId) orgId = requested;

  const userId = readUserId(c);
  if (userId) {
    const role = await getCachedMembershipRole(orgId, userId);
    if (role) return orgId;
    logger.warn(
      { requested, orgId },
      "Rejecting explicit install org: user is not a member"
    );
    return null;
  }

  // No authenticated user (self-host): only honor the requested org when it is
  // the single tenant, so a stray ?org= can't select a foreign tenant.
  const single = await resolveSingleTenantOrgId();
  return single !== null && single === orgId ? orgId : null;
}

/**
 * Resolve the install-flow org for the current request.
 *
 * Precedence:
 *   1. Explicit `?org=<slug|id>` from the install link — the org the user chose
 *      in the UI, authorized by membership ({@link resolveRequestedOrgId}). When
 *      present but unauthorized/unknown, returns `null` so the route rejects
 *      rather than silently falling back to a different org.
 *   2. The session-bound active org (legacy links, CLI).
 *   3. The self-host single-tenant fallback.
 *
 * Shared by every app-installation flow (the generic install engine in
 * `app-install.ts`), so it lives here rather than in any one provider's module.
 */
export async function resolveInstallOrgId(c: Context): Promise<string | null> {
  const requested = c.req.query("org")?.trim();
  if (requested) {
    return resolveRequestedOrgId(c, requested);
  }
  const sessionOrgId = readSessionOrgId(c);
  if (sessionOrgId) return sessionOrgId;
  return resolveSingleTenantOrgId();
}

/**
 * Authorize install-flow COMPLETION against the org the install was started for
 * (carried in the signed OAuth state). Used by the callback instead of
 * re-deriving the ambient active org and comparing it to the state's org: that
 * comparison rejects a legitimate install whenever the user's active org drifted
 * from the org they launched the install from (the UI-selected org threaded via
 * `?org=`). Membership is the real authorization — the state org was already
 * membership-checked at start, so the callback just re-confirms the completing
 * user still belongs to it.
 *
 * On self-host (no authenticated user) the org is authorized only when it is the
 * sole tenant.
 */
export async function verifyInstallOrgAccess(
  c: Context,
  organizationId: string
): Promise<boolean> {
  const userId = readUserId(c);
  if (userId) {
    const role = await getCachedMembershipRole(organizationId, userId);
    return role !== null;
  }
  const single = await resolveSingleTenantOrgId();
  return single !== null && single === organizationId;
}
/**
 * Guard against creating an UNBOUND `app_installation` connection.
 *
 * When a connector's primary auth method is `app_installation` (e.g. github),
 * a connection bound to an install is created by the App install callback's
 * `linkGithubAppInstallation`, which stamps `config.installation_ref`. The guard
 * rejects a create/connect that would resolve to `app_installation` auth with no
 * `installation_ref` — a dead, unbound connection — and points the user at the
 * install flow.
 *
 * SELECTION-AWARE: it must NOT block a connection that resolves to a DIFFERENT
 * auth method. github also declares oauth + env_keys, so a legit create/connect
 * that supplies an auth profile slug, env/PAT creds in config, or a managedBy
 * grant uses one of those methods — the guard skips entirely. Only when no such
 * intent is present (and there is no installation_ref) does the connection fall
 * through to the app_installation primary, which is what we reject.
 *
 * RESOLVED, NOT ASSERTED: a passed `auth_profile_slug` / `app_auth_profile_slug`
 * only satisfies the guard when it RESOLVES to a real auth profile for this
 * org/connector (same resolver the create/connect flow uses). A non-existent or
 * non-resolvable slug is treated as if no slug was provided — otherwise a caller
 * could assert a bogus slug to bypass the guard and create a dead, unbound
 * app_installation connection.
 *
 * Connector-agnostic: keys on the resolved auth method type (not on `github`),
 * so it covers any future app_installation connector.
 */

import { parseJsonObject } from '@lobu/core';
import { buildConnectionsUrl } from '../../../utils/url-builder';
import { resolveAuthProfileSlugToId } from '../../../utils/auth-profiles';
import type { ToolContext } from '../../registry';
import { getOrgUrlContext } from '../../view-urls';
import {
  getAppInstallationAuthMethods,
  getEnvAuthFieldKeys,
  isPrimaryAuthMethodAppInstallation,
  normalizeConnectorAuthSchema,
} from '../../../utils/connector-auth';
import {
  buildAppInstallationSetupError,
  type ConnectorSetupError,
} from './connector-setup-errors';

export async function buildAppInstallationSetupUrl(
  ctx: ToolContext,
  connectorKey: string,
): Promise<string | undefined> {
  const { ownerSlug, baseUrl } = await getOrgUrlContext(ctx);
  return ownerSlug && baseUrl
    ? buildConnectionsUrl(ownerSlug, baseUrl, undefined, {
        install: connectorKey,
      })
    : undefined;
}

function hasInstallationRef(config: Record<string, unknown>): boolean {
  const ref = config.installation_ref;
  return (
    (typeof ref === 'number' && Number.isFinite(ref)) ||
    (typeof ref === 'string' && ref.trim().length > 0)
  );
}

function hasManagedByOrg(config: Record<string, unknown>): boolean {
  const managedBy = config.managedBy;
  if (!managedBy || typeof managedBy !== 'object' || Array.isArray(managedBy)) {
    return false;
  }
  const org = (managedBy as Record<string, unknown>).org;
  return typeof org === 'string' && org.trim().length > 0;
}

/**
 * Returns a structured connector-setup error to short-circuit the create/connect
 * handler when the connection would be an unbound app_installation connection,
 * else null.
 *
 * The caller passes the auth-INTENT signals it received so the guard can tell a
 * deliberate oauth/PAT/env/managed create from a bare one that falls through to
 * app_installation. An asserted auth-profile slug is RESOLVED against the org's
 * auth profiles (not trusted as a bare string) so a bogus slug can't bypass it.
 *
 * @param organizationId      the org the connection is being created in (slug scope)
 * @param authSchema          the connector definition's `auth_schema` (raw jsonb/string)
 * @param config              the connection `config` being created
 * @param connectorKey        for the (connector-agnostic) error message + slug scope
 * @param authProfileSlug     an explicitly selected credential profile (env/oauth_account/browser/interactive — NOT oauth_app)
 * @param appAuthProfileSlug  an explicitly selected OAuth app profile (oauth_app only)
 */
export async function rejectUnboundAppInstallationCreate(params: {
  organizationId: string;
  authSchema: unknown;
  config: unknown;
  connectorKey: string;
  authProfileSlug?: string | null;
  appAuthProfileSlug?: string | null;
  gatewayBaseUrl?: string;
  setupUrl?: string;
}): Promise<ConnectorSetupError | null> {
  const schema = normalizeConnectorAuthSchema(params.authSchema);
  // Only connectors whose PRIMARY method is app_installation are in scope.
  if (!isPrimaryAuthMethodAppInstallation(schema)) return null;

  const config = parseJsonObject(params.config);

  // Already bound (the install-callback shape) → allow.
  if (hasInstallationRef(config)) return null;

  // A deliberate non-app_installation auth selection → the connection will use
  // THAT method, not app_installation. Skip the guard — but only when the slug
  // RESOLVES to a real profile OF THE RIGHT KIND for this org/connector. An
  // asserted-but-bogus slug, OR one that resolves to the wrong kind for its
  // param, must NOT satisfy the guard (it would create a dead, unbound
  // app_installation connection), so resolve + kind-check it the same way the
  // create/connect flow does before trusting it as an alternate auth selection.
  //
  // `auth_profile_slug` is the connection's CREDENTIAL profile — any kind that
  // actually provides connection auth (env / oauth_account / browser_session /
  // interactive). An `oauth_app` carries only the app's client_id/secret, not
  // the connection's credentials, so it does NOT satisfy auth_profile_slug.
  if (params.authProfileSlug?.trim()) {
    const resolved = await resolveAuthProfileSlugToId({
      organizationId: params.organizationId,
      slug: params.authProfileSlug,
      connectorKey: params.connectorKey,
    });
    if (resolved && resolved.profile_kind !== 'oauth_app') return null;
  }
  // `app_auth_profile_slug` selects the OAuth app (local client credentials);
  // only an `oauth_app` profile is a valid target. resolveAuthProfileSlugToId's
  // expectedKind enforces that — a wrong-kind slug resolves to null here.
  if (params.appAuthProfileSlug?.trim()) {
    const resolvedApp = await resolveAuthProfileSlugToId({
      organizationId: params.organizationId,
      slug: params.appAuthProfileSlug,
      connectorKey: params.connectorKey,
      expectedKind: 'oauth_app',
    });
    if (resolvedApp) return null;
  }
  if (hasManagedByOrg(config)) return null;
  // Env/PAT creds supplied directly in config (e.g. GITHUB_TOKEN) → env auth.
  const envKeys = getEnvAuthFieldKeys(schema);
  if (envKeys.some((key) => config[key] !== undefined && config[key] !== null)) {
    return null;
  }

  // No installation_ref and no other auth intent → this would resolve to the
  // app_installation primary with nothing to bind. Reject with install guidance.
  const method = getAppInstallationAuthMethods(schema)[0];
  if (!method) return null;
  return buildAppInstallationSetupError({
    connectorKey: params.connectorKey,
    method,
    gatewayBaseUrl: params.gatewayBaseUrl,
    setupUrl: params.setupUrl,
  });
}
import { randomUUID } from "node:crypto";
import { isSecretKey } from "@lobu/core";
import type {
	ConnectCompletionCheckType,
	ConnectSdkCallType,
	ConnectSetupFamilyType,
	ConnectSetupNextActionType,
	ManageConnectionsResult,
} from "@lobu/core/contracts/tools/manage-connections";
import type { ConnectorSetupError } from "./connector-setup-errors";

export type ConnectionSetupFamily = ConnectSetupFamilyType;
export type ConnectionSetupNextAction = ConnectSetupNextActionType;
export type SdkCallDescriptor = ConnectSdkCallType;
type SetupCompletionCheck = ConnectCompletionCheckType;

function omitSecretValues(value: unknown): unknown {
	if (Array.isArray(value)) return value.map(omitSecretValues);
	if (!value || typeof value !== "object") return value;
	return Object.fromEntries(
		Object.entries(value as Record<string, unknown>)
			.filter(([key]) => !isSecretKey(key))
			.map(([key, child]) => [key, omitSecretValues(child)]),
	);
}

function omitUndefinedProperties(
	value: Record<string, unknown>,
): Record<string, unknown> {
	return Object.fromEntries(
		Object.entries(value).filter(([, child]) => child !== undefined),
	);
}

/**
 * Build a retry descriptor without reflecting caller-supplied secrets back to
 * the agent. Secret keys are omitted instead of replaced: a redaction sentinel
 * in an executable call could be mistaken for a real credential on resume.
 */
export function buildSafeConnectionResumeCall(
	sdkMethod: "connections.connect" | "connections.create",
	args: object,
): SdkCallDescriptor {
	const safeArgs = omitSecretValues(args) as Record<string, unknown>;
	delete safeArgs.action;
	return {
		sdk_method: sdkMethod,
		arguments: [safeArgs],
	};
}

interface ConnectionSetupContinuationInput {
	action: "connect" | "create";
	connectorKey: string;
	setupFamily: ConnectionSetupFamily;
	nextAction: ConnectionSetupNextAction;
	instructions: string;
	resumeCall?: SdkCallDescriptor;
	completionCheck?: SetupCompletionCheck;
	setupUrl?: string;
	installUrl?: string;
	connectUrl?: string;
	provider?: string;
	connectionId?: number;
	slug?: string;
	authRunId?: number;
	setupAttemptId?: string;
	errorCode?: "connector_setup_required";
	installType?: "app_installation" | "oauth_app_profile";
	installShape?: "oauth-code-exchange" | "github-app";
	setupInstructions?: string;
}

/**
 * A setup continuation is deliberately a successful SDK result: no `error`
 * field means `run_sdk` returns it intact for the agent to act on. The three
 * affordances are separate: `next_action` is the user step, `resume_call` is
 * the exact SDK call after manual setup, and `completion_check` is present
 * only when it can be invoked immediately using values in this result.
 */
export function buildConnectionSetupContinuation(
	input: ConnectionSetupContinuationInput,
): ManageConnectionsResult {
	return omitUndefinedProperties({
		action: input.action,
		status: "setup_required",
		connector_key: input.connectorKey,
		setup_family: input.setupFamily,
		next_action: input.nextAction,
		instructions: input.instructions,
		error_code: input.errorCode,
		install_type: input.installType,
		install_shape: input.installShape,
		setup_instructions: input.setupInstructions,
		resume_call: input.resumeCall,
		completion_check: input.completionCheck,
		setup_url: input.setupUrl,
		install_url: input.installUrl,
		connect_url: input.connectUrl,
		provider: input.provider,
		connection_id: input.connectionId,
		slug: input.slug,
		auth_run_id: input.authRunId,
		setup_attempt_id: input.setupAttemptId,
	}) as ManageConnectionsResult;
}

export function activeConnectionPoll(
	connectionId: number,
): SetupCompletionCheck {
	return {
		call: {
			sdk_method: "connections.get",
			arguments: [connectionId],
		},
		success_when: { path: "connection.status", equals: "active" },
		poll_interval_ms: 2000,
		description: "Poll until the connection becomes active.",
	};
}

export function installedConnectorPoll(
	connectorKey: string,
	setupAttemptId: string,
): SetupCompletionCheck {
	return {
		call: {
			sdk_method: "connections.list",
			arguments: [
				{
					connector_key: connectorKey,
					status: "active",
					setup_attempt_id: setupAttemptId,
				},
			],
		},
		success_when: {
			path: "connections[].config.setup_attempt_ids",
			includes: setupAttemptId,
		},
		poll_interval_ms: 2000,
		description:
			"Poll until the provider callback marks this exact setup attempt active.",
	};
}

export function appendSetupAttemptId(
	installUrl: string,
	setupAttemptId: string,
): string {
	const url = new URL(installUrl);
	url.searchParams.set("setup_attempt_id", setupAttemptId);
	return url.toString();
}

export function appInstallationSetupContinuation(params: {
	action: "connect" | "create";
	connectorKey: string;
	setup: ConnectorSetupError;
	setupUrl?: string;
}): ManageConnectionsResult {
	const { action, connectorKey, setup, setupUrl } = params;
	const setupAttemptId =
		setup.provider === "github" && setup.install_url ? randomUUID() : undefined;
	return buildConnectionSetupContinuation({
		action,
		connectorKey,
		setupFamily: "app_installation",
		nextAction:
			setup.next_action === "install_app" ? "install_app" : "open_setup",
		instructions: setup.error,
		errorCode: setup.error_code,
		installType: setup.install_type,
		installShape: setup.install_shape,
		setupInstructions: setup.setup_instructions,
		setupUrl,
		installUrl:
			setup.install_url && setupAttemptId
				? appendSetupAttemptId(setup.install_url, setupAttemptId)
				: setup.install_url,
		provider: setup.provider,
		completionCheck: setupAttemptId
			? installedConnectorPoll(connectorKey, setupAttemptId)
			: undefined,
		setupAttemptId,
	});
}

export function oauthAppSetupContinuation(params: {
	action: "connect" | "create";
	connectorKey: string;
	setup: ConnectorSetupError;
	resumeCall: SdkCallDescriptor;
	fallbackSetupUrl?: string;
}): ManageConnectionsResult {
	const { action, connectorKey, setup, resumeCall, fallbackSetupUrl } = params;
	return buildConnectionSetupContinuation({
		action,
		connectorKey,
		setupFamily: "oauth",
		nextAction: "configure_oauth_app",
		instructions: setup.setup_instructions
			? `${setup.error} ${setup.setup_instructions}`
			: setup.error,
		setupUrl: setup.setup_url ?? fallbackSetupUrl,
		provider: setup.provider,
		errorCode: setup.error_code,
		installType: setup.install_type,
		setupInstructions: setup.setup_instructions,
		resumeCall,
	});
}
