   if (appInstallGuard) {
 		// Setup-required continuation: the App install callback creates the active
 		// connection itself, so do NOT instruct a retry of connect. The guard's
 		// ConnectorSetupError already carries the absolute install_url.
-		return appInstallationSetupContinuation({
+		const setupContinuation = appInstallationSetupContinuation({
 			action: "connect",
 			connectorKey: args.connector_key,
 			setup: appInstallGuard,
 			setupUrl: await buildAppInstallationSetupUrl(ctx, args.connector_key),
 		});
+		if (
+			!userId ||
+			(ctx.tokenType !== "oauth" && ctx.tokenType !== "session") ||
+			!("install_url" in setupContinuation) ||
+			typeof setupContinuation.install_url !== "string"
+		) {
+			return setupContinuation;
+		}
+
+		// Connections remain workspace-scoped, but a human OAuth/session identity
+		// may belong to several workspaces. Before telling them to install the same
+		// provider app again, surface active install-backed connections in OTHER
+		// workspaces they can access. This query returns only workspace/connection
+		// identity — never app-install metadata, config, credentials, or repository
+		// data. PATs stay strictly pinned to their token workspace.
+		const otherRows = (await sql`
+			SELECT o.id AS organization_id, o.slug AS organization_slug,
+			       o.name AS organization_name, c.id AS connection_id,
+			       c.slug AS connection_slug, c.display_name
+			FROM "member" m
+			JOIN organization o ON o.id = m."organizationId"
+			JOIN connections c ON c.organization_id = o.id
+			JOIN app_installations ai
+			  ON ai.organization_id = c.organization_id
+			 AND ai.id::text = c.config ->> 'installation_ref'
+			WHERE m."userId" = ${userId}
+			  AND o.id <> ${organizationId}
+			  AND c.connector_key = ${args.connector_key}
+			  AND c.status = 'active'
+			  AND c.deleted_at IS NULL
+			  AND ai.status = 'active'
+			ORDER BY o.slug ASC, c.id ASC
+			LIMIT 20
+		`) as unknown as Array<{
+			organization_id: string;
+			organization_slug: string;
+			organization_name: string;
+			connection_id: number;
+			connection_slug: string;
+			display_name: string | null;
+		}>;
+		if (otherRows.length === 0 || !ownerSlug) return setupContinuation;
+
+		const currentRows = (await sql`
+			SELECT name FROM organization WHERE id = ${organizationId} LIMIT 1
+		`) as unknown as Array<{ name: string }>;
+		const installUrl = new URL(setupContinuation.install_url);
+		installUrl.searchParams.set("org", ownerSlug);
+		const transferUrl = new URL(installUrl);
+		transferUrl.searchParams.set("recovery", "1");
+		transferUrl.searchParams.set("confirm_transfer", "1");
+		const canTransfer =
+			appInstallGuard.provider === "github" &&
+			appInstallGuard.install_shape === "github-app" &&
+			(ctx.memberRole === "owner" || ctx.memberRole === "admin");
+
+		return {
+			action: "connect",
+			status: "connected_in_other_workspace",
+			connector_key: args.connector_key,
+			current_workspace: {
+				id: organizationId,
+				slug: ownerSlug,
+				name: currentRows[0]?.name ?? ownerSlug,
+			},
+			accessible_workspaces: otherRows.map((row) => ({
+				workspace: {
+					id: row.organization_id,
+					slug: row.organization_slug,
+					name: row.organization_name,
+				},
+				connection: {
+					id: Number(row.connection_id),
+					slug: row.connection_slug,
+					display_name: row.display_name,
+					status: "active" as const,
+				},
+				switch_workspace: {
+					next_action: "switch_workspace" as const,
+					organization_id: row.organization_id,
+					organization_slug: row.organization_slug,
+					view_url: buildConnectionsUrl(
+						row.organization_slug,
+						baseUrl,
+						args.connector_key,
+					),
+				},
+			})),
+			install_app_here: {
+				next_action: "install_app",
+				install_url: installUrl.toString(),
+			},
+			...(canTransfer
+				? {
+						transfer_installation_here: {
+							next_action: "transfer_installation_here" as const,
+							transfer_url: transferUrl.toString(),
+							requires_confirmation: true as const,
+							warning:
+								"This moves the selected GitHub App installation here and revokes its connection in the previous workspace.",
+						},
+					}
+				: {}),
+			instructions:
+				"This connector is already active in another workspace you can access. Switch to that workspace, install a different app tenant here, or use the explicit admin-confirmed transfer action. No connection data or credentials are shared across workspaces.",
+		};
   }
*** End Patch";
