export function installedConnectorPoll(
	connectorKey: string,
	setupAttemptId: string,
): SetupCompletionCheck {
	return {
		call: {
			sdk_method: "connections.list",
			arguments: [
				{
					connector_key: connectorKey,
					status: "active",
					setup_attempt_id: setupAttemptId,
				},
			],
		},
		success_when: {
			path: "connections[].config.setup_attempt_ids",
			includes: setupAttemptId,
		},
		poll_interval_ms: 2000,
		description:
			"Poll until the provider callback marks this exact setup attempt active.",
	};
}

export function appendSetupAttemptId(
	installUrl: string,
	setupAttemptId: string,
): string {
	const url = new URL(installUrl);
	url.searchParams.set("setup_attempt_id", setupAttemptId);
	return url.toString();
}

export function appInstallationSetupContinuation(params: {
	action: "connect" | "create";
	connectorKey: string;
	setup: ConnectorSetupError;
	setupUrl?: string;
}): ManageConnectionsResult {
	const { action, connectorKey, setup, setupUrl } = params;
	const setupAttemptId =
		setup.provider === "github" && setup.install_url ? randomUUID() : undefined;
	return buildConnectionSetupContinuation({
		action,
		connectorKey,
		setupFamily: "app_installation",
		nextAction:
			setup.next_action === "install_app" ? "install_app" : "open_setup",
		instructions: setup.error,
		errorCode: setup.error_code,
		installType: setup.install_type,
		installShape: setup.install_shape,
		setupInstructions: setup.setup_instructions,
		setupUrl,
		installUrl:
			setup.install_url && setupAttemptId
				? appendSetupAttemptId(setup.install_url, setupAttemptId)
				: setup.install_url,
		provider: setup.provider,
		completionCheck: setupAttemptId
			? installedConnectorPoll(connectorKey, setupAttemptId)
			: undefined,
		setupAttemptId,
	});
}

export function oauthAppSetupContinuation(params: {
	action: "connect" | "create";
	connectorKey: string;
	setup: ConnectorSetupError;
	resumeCall: SdkCallDescriptor;
	fallbackSetupUrl?: string;
}): ManageConnectionsResult {
	const { action, connectorKey, setup, resumeCall, fallbackSetupUrl } = params;
	return buildConnectionSetupContinuation({
		action,
		connectorKey,
		setupFamily: "oauth",
		nextAction: "configure_oauth_app",
		instructions: setup.setup_instructions
			? `${setup.error} ${setup.setup_instructions}`
			: setup.error,
		setupUrl: setup.setup_url ?? fallbackSetupUrl,
		provider: setup.provider,
		errorCode: setup.error_code,
		installType: setup.install_type,
		setupInstructions: setup.setup_instructions,
		resumeCall,
	await ensureConnectorInstalled({
		organizationId,
		connectorKey: args.connector_key,
	});

  // Verify connector exists
  const connector = await getScopedConnectorDefinition({
    organizationId,
    connectorKey: args.connector_key,
  });

  if (!connector) {
    return {
      error: `Connector '${args.connector_key}' not found. Install it first from the connections page.`,
      setup_url: buildSetupUrl({ install: args.connector_key }),
    };
  }

  const setupUrl = buildSetupUrl({ connectorKey: args.connector_key });

  // Reject a direct connect of an UNBOUND app_installation connection (no
  // installation_ref AND no other auth intent) — those are created only by the
  // App install callback. Selection-aware: a connect that supplies an auth
  // profile / app profile / env creds / managedBy resolves to a different method
  // and is allowed through.
  const appInstallGuard = await rejectUnboundAppInstallationCreate({
    organizationId,
    authSchema: connector.auth_schema,
    config: args.config,
    connectorKey: args.connector_key,
    authProfileSlug: args.auth_profile_slug,
    appAuthProfileSlug: args.app_auth_profile_slug,
    gatewayBaseUrl: getGatewayBaseUrl(ctx),
    setupUrl,
  });
  if (appInstallGuard) {
		// Setup-required continuation: the App install callback creates the active
		// connection itself, so do NOT instruct a retry of connect. The guard's
		// ConnectorSetupError already carries the absolute install_url.
		const setupContinuation = appInstallationSetupContinuation({
			action: "connect",
			connectorKey: args.connector_key,
			setup: appInstallGuard,
			setupUrl: await buildAppInstallationSetupUrl(ctx, args.connector_key),
		});
		if (
			!userId ||
			(ctx.tokenType !== "oauth" && ctx.tokenType !== "session") ||
			!appInstallGuard.provider_instance ||
			!("install_url" in setupContinuation) ||
			typeof setupContinuation.install_url !== "string"
		) {
			return setupContinuation;
		}

		// Connections remain workspace-scoped, but a human OAuth/session identity
		// may belong to several workspaces. Before telling them to install the same
		// provider app again, surface active install-backed connections in OTHER
		// workspaces they can access. This query returns only workspace/connection
		// identity — never app-install metadata, config, credentials, or repository
		// data.
		//
		// PATs stay pinned to their token workspace. The interactive OAuth/session
		// path deliberately works from `/mcp/{slug}`: that is the failing setup flow,
		// and membership gates every workspace identity returned here.
		//
		// Per-source-workspace visibility mirrors `connections.list` in that
		// workspace (see authz/connection-visibility): org-visible rows, the
		// caller's own private rows, and — for an owner/admin there — the whole
		// management view. Without it a plain member of workspace B would learn the
		// slug of another member's PRIVATE connection, and could be handed a
		// transfer option aimed at it.
		const otherRows = (await sql`
			SELECT o.id AS organization_id, o.slug AS organization_slug,
			       o.name AS organization_name, c.id AS connection_id,
			       c.slug AS connection_slug, c.display_name,
			       m.role AS source_member_role
			FROM "member" m
			JOIN organization o ON o.id = m."organizationId"
			JOIN connections c ON c.organization_id = o.id
			JOIN app_installations ai
			  ON ai.organization_id = c.organization_id
			 AND ai.id::text = c.config ->> 'installation_ref'
			WHERE m."userId" = ${userId}
			  AND o.id <> ${organizationId}
			  AND c.connector_key = ${args.connector_key}
			  AND c.status = 'active'
			  AND c.deleted_at IS NULL
			  AND ai.status = 'active'
			  AND ai.provider = ${appInstallGuard.provider}
			  AND ai.provider_instance = ${appInstallGuard.provider_instance}
			  AND (
			    m.role IN ('owner', 'admin')
			    OR c.visibility = 'org'
			    OR c.created_by = ${userId}
			  )
			ORDER BY o.slug ASC, c.id ASC
		`) as unknown as Array<{
			organization_id: string;
			organization_slug: string;
			organization_name: string;
			connection_id: number;
			connection_slug: string;
			display_name: string | null;
			source_member_role: string;
		}>;
		if (otherRows.length === 0 || !ownerSlug) return setupContinuation;

