// Standalone regression test for the device-held finalize loop in
// `BehaviorDispatcher.dispatch` — the orchestration that decides durable
// delivery state for a Behavior run.
//
// The helpers around it were already covered (`CompleteBehaviorResponseTests`
// pins how one 2xx body is read); the loop that consumes those reports was not.
// That loop is where the costly mistakes live: re-spawning the CLI when the
// server only wanted the report re-sent, consuming a fresh finalize attempt on
// a retry, or answering an ambiguous delivery with a contradictory failure
// report that overwrites a decision the server already committed.
//
// Both seams needed already exist in production code, so nothing here is a
// test-only affordance: `LocalAgentExecutor` is a protocol, and
// `WorkerClient.init` takes an injectable `URLSession`. The stub below drives
// the real `WorkerClient` over a real `URLSession`, so the wire body — the
// `finalize_attempt` the server actually receives — is what gets asserted.
//
//   swiftc apps/mac/Owletto/BehaviorDispatcher.swift \
//          apps/mac/Owletto/Log.swift \
//          apps/mac/Owletto/LocalAgentDetector.swift \
//          apps/mac/Owletto/LobuClient.swift \
//          apps/mac/Owletto/DeviceConnectorManifests.swift \
//          apps/mac/Tests/DispatcherResumeTests.swift -o /tmp/dispatcher-resume-test \
//   && /tmp/dispatcher-resume-test

import Foundation

// Minimal stub for an unrelated LobuClient reference, matching AnyEncodableTests.
extension String {
    func trimmedTrailingSlash() -> String {
        var s = self
        while s.hasSuffix("/") { s.removeLast() }
        return s
    }
    static let jobJSON = """
        {"run_id":4242,"run_type":"behavior","organization_id":"org_test",
         "payload":{
           "behavior":{"id":"beh_1","name":"Test","slug":"test","agent_kind":"claude-code",
                      "notification_channel":null,"notification_priority":null,
                      "execution_config":{"timeout_seconds":5},
                      "prompt":"do a thing","extraction_schema":null},
           "event":{"trigger_event_id":null,"fired_at":"2026-07-30T00:00:00Z","payload":null},
           "context":{"device":{"worker_id":"wrk_1"},"user":{"user_id":"usr_1"}}}}
        """

    /// One dispatch against a scripted server. Returns the spawn nudges and the
    /// `finalize_attempt` carried by each posted report.
    static func dispatch(
        _ replies: [StubURLProtocol.Reply]
    ) async throws -> (nudges: [String?], attempts: [Int?]) {
        StubURLProtocol.script(replies)
        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [StubURLProtocol.self]
        let client = WorkerClient(
            baseURL: "https://stub.invalid", accessToken: "t",
            session: URLSession(configuration: config))
        let executor = RecordingExecutor()
        let job = try JSONDecoder().decode(BehaviorJob.self, from: Data(jobJSON.utf8))

        await BehaviorDispatcher(executors: [executor])
            .dispatch(job: job, client: client, workerId: "wrk_1")

        let attempts = StubURLProtocol.completions.map { body -> Int? in
            let obj = try? JSONSerialization.jsonObject(with: body) as? [String: Any]
            return (obj?["finalize_attempt"] as? NSNumber)?.intValue
        }
        return (executor.nudges, attempts)
    }

    static func main() async throws {
        // 1. A granted resume re-spawns the CLI with the server's nudge, and the
        //    next report carries the server's attempt number — not a local
        //    increment, so the row stays the authority on the budget.
        //
        //    The scripted attempt is deliberately 2, not 1: after one resume a
        //    local `+ 1` would also produce 1, so a 1 here would pass whether or
        //    not the server's count is being honoured.
        let resumed = try await dispatch([
            .init(
                status: 200,
                body: #"{"ok":true,"status":"resume","attempt":2,"max_attempts":3,"nudge":"finalize it"}"#),
            .init(status: 200, body: #"{"ok":true,"status":"completed"}"#),
        ])
        check(resumed.nudges.count == 2, "a granted resume must spawn the CLI a second time")
        check(resumed.nudges.first == .some(nil), "the first spawn carries no nudge")
