export function eventDedupLockKey(connectionId: number, originId: string): number {
  let hash = 0x811c9dc5;
  const s = `${connectionId}:${originId}`;
  for (let i = 0; i < s.length; i++) {
    hash ^= s.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash | 0;
}

