  violations: Violation[],
  file: string,
  source: ts.SourceFile,
  node: ts.Node
): void {
  const start = node.getStart(source);
  const { line } = source.getLineAndCharacterOfPosition(start);
  const text = source.text.split("\n")[line]?.trim() ?? "";
  violations.push({
    file: rel(file),
    line: line + 1,
    excerpt: text.slice(0, 120),
